#include <iostream>
#include <fstream>
#include <string>
#include <cstring>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <filesystem>
#include <memory>
#include <vector>
#include <sstream>
#include <mutex>

namespace fs = std::filesystem;

class SecureStorageConfig {
public:
    static constexpr int KEY_SIZE = 32;
    static constexpr int IV_SIZE = 16;
    static constexpr int BLOCK_SIZE = 16;
    static constexpr mode_t DIR_PERMS = 0700;
    static constexpr mode_t FILE_PERMS = 0600;

    static std::string getTempDirectory() {
        const char* secure_tmp = getenv("SECURE_TMPDIR");
        if (secure_tmp && fs::exists(secure_tmp)) {
            return std::string(secure_tmp);
        }
        return "/tmp/secure_processing";
    }
};

class CryptoEngine {
private:
    std::vector<unsigned char> key_;
    std::mutex mtx_;

public:
    CryptoEngine() : key_(SecureStorageConfig::KEY_SIZE) {
        if (RAND_bytes(key_.data(), SecureStorageConfig::KEY_SIZE) != 1) {
            throw std::runtime_error("Failed to generate encryption key");
        }
    }

    std::vector<unsigned char> encrypt(const std::vector<unsigned char>& plaintext) {
        std::lock_guard<std::mutex> lock(mtx_);
        std::vector<unsigned char> iv(SecureStorageConfig::IV_SIZE);
        // Check RNG return value: a failed RAND_bytes must not silently
        // produce a predictable/zeroed IV.
        if (RAND_bytes(iv.data(), SecureStorageConfig::IV_SIZE) != 1) {
            throw std::runtime_error("Failed to generate IV");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        std::unique_ptr<EVP_CIPHER_CTX, decltype(&EVP_CIPHER_CTX_free)> 
            ctx_guard(ctx, EVP_CIPHER_CTX_free);

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key_.data(), iv.data()) != 1) {
            throw std::runtime_error("Failed to initialize encryption");
        }

        std::vector<unsigned char> ciphertext(plaintext.size() + SecureStorageConfig::BLOCK_SIZE + SecureStorageConfig::IV_SIZE);
        std::memcpy(ciphertext.data(), iv.data(), SecureStorageConfig::IV_SIZE);

        int len = 0, total = SecureStorageConfig::IV_SIZE;
        if (EVP_EncryptUpdate(ctx, ciphertext.data() + total, &len, plaintext.data(), plaintext.size()) != 1) {
            throw std::runtime_error("Encryption update failed");
        }
        total += len;
        if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + total, &len) != 1) {
            throw std::runtime_error("Encryption finalization failed");
        }
        total += len;
        ciphertext.resize(total);
        return ciphertext;
    }
};

class TempFileManager {
private:
    std::string base_dir_;
    std::vector<int> tracked_fds_;
    std::vector<std::string> tracked_paths_;
    std::mutex file_mtx_;

    std::string generateTemplate(const std::string& prefix) {
        return base_dir_ + "/" + prefix + "_XXXXXX";
    }

public:
    TempFileManager(const std::string& base_dir) : base_dir_(base_dir) {
        fs::create_directories(base_dir_);
        chmod(base_dir_.c_str(), SecureStorageConfig::DIR_PERMS);
    }

    int createSecureTempFile(const std::string& prefix, std::string& out_path) {
        std::lock_guard<std::mutex> lock(file_mtx_);
        std::string tmpl = generateTemplate(prefix);
        std::vector<char> tmpl_buf(tmpl.begin(), tmpl.end());
        tmpl_buf.push_back('\0');

        // Use mkstemp for atomic creation - no TOCTOU race
        int fd = mkstemp(tmpl_buf.data());
        if (fd < 0) {
            throw std::runtime_error("Failed to create secure temp file");
        }

        // Set restrictive permissions on the already-open fd
        fchmod(fd, SecureStorageConfig::FILE_PERMS);

        out_path = std::string(tmpl_buf.data());
        tracked_fds_.push_back(fd);
        tracked_paths_.push_back(out_path);
        return fd;
    }

    void writeEncryptedDataFd(int fd, const std::vector<unsigned char>& data) {
        lseek(fd, 0, SEEK_SET);
        ftruncate(fd, 0);
        ssize_t written = write(fd, data.data(), data.size());
        if (written != static_cast<ssize_t>(data.size())) {
            throw std::runtime_error("Failed to write all data");
        }
        fsync(fd);
    }

    std::vector<unsigned char> readDataFd(int fd) {
        struct stat st;
        fstat(fd, &st);
        std::vector<unsigned char> data(st.st_size);
        lseek(fd, 0, SEEK_SET);
        read(fd, data.data(), data.size());
        return data;
    }

    ~TempFileManager() {
        for (size_t i = 0; i < tracked_fds_.size(); i++) {
            // Secure deletion: overwrite before unlink
            struct stat st;
            if (fstat(tracked_fds_[i], &st) == 0) {
                std::vector<unsigned char> zeros(st.st_size, 0);
                lseek(tracked_fds_[i], 0, SEEK_SET);
                write(tracked_fds_[i], zeros.data(), zeros.size());
                fsync(tracked_fds_[i]);
            }
            close(tracked_fds_[i]);
            if (i < tracked_paths_.size()) {
                unlink(tracked_paths_[i].c_str());
            }
        }
    }
};

class FileProcessingService {
private:
    CryptoEngine crypto_;
    std::unique_ptr<TempFileManager> temp_mgr_;

public:
    FileProcessingService() {
        std::string tmp_dir = SecureStorageConfig::getTempDirectory();
        temp_mgr_ = std::make_unique<TempFileManager>(tmp_dir);
    }

    bool processAndStore(const std::string& input_path, 
                        const std::string& output_path) {
        // Read input file
        std::ifstream input(input_path, std::ios::binary);
        if (!input.is_open()) return false;

        std::vector<unsigned char> content(
            (std::istreambuf_iterator<char>(input)),
            std::istreambuf_iterator<char>());
        input.close();

        // Create temp file for intermediate processing - uses fd throughout
        std::string temp_path;
        int temp_fd = temp_mgr_->createSecureTempFile("proc", temp_path);

        // Write plaintext to temp fd for processing stage
        temp_mgr_->writeEncryptedDataFd(temp_fd, content);

        // Simulate processing delay (transformation stage)
        usleep(100000);

        // Re-read processed data using the same fd (no TOCTOU)
        auto proc_data = temp_mgr_->readDataFd(temp_fd);

        // Encrypt and write to final destination
        auto encrypted = crypto_.encrypt(proc_data);

        // Use O_CREAT|O_EXCL for output to prevent symlink attacks
        int out_fd = open(output_path.c_str(), 
                         O_CREAT | O_WRONLY | O_TRUNC | O_NOFOLLOW,
                         SecureStorageConfig::FILE_PERMS);
        if (out_fd < 0) return false;

        write(out_fd, encrypted.data(), encrypted.size());
        fsync(out_fd);
        close(out_fd);

        return true;
    }
};

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " <input> <output>" << std::endl;
        return 1;
    }

    try {
        FileProcessingService service;
        if (service.processAndStore(argv[1], argv[2])) {
            std::cout << "File processed and encrypted successfully." << std::endl;
            return 0;
        } else {
            std::cerr << "Processing failed." << std::endl;
            return 1;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
}
